-- One-time snapshot import from the six desktop JSON exports.
-- Pre-tax formula: (source product USD + 37.23 USD FedEx Economy shipping at 4 lb) * 3.75 SAR/USD.
-- Prices include US-to-Saudi shipping; tax is intentionally excluded pending the user's tax rules.
-- Product source URLs are not stored. product_key is SHA-256 of the canonical source URL.
-- Variable-price records without a single safe displayed price are omitted.
on conflict (product_key) do update set
  brand = excluded.brand,
  name = excluded.name,
  image_url = excluded.image_url,
  delivered_price_sar = excluded.delivered_price_sar,
  is_published = excluded.is_published,
  updated_at = now();
